item = _items[0]["json"]
src = item.get("body") if isinstance(item.get("body"), dict) else item


def text(value):
    return "" if value is None else str(value).strip()


def num(value):
    if value is None or value == "":
        return None
    try:
        return float(str(value).replace(",", ""))
    except (TypeError, ValueError):
        return None


def round2(value):
    return round(value + 1e-12, 2)


def to_bool(value, default=True):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {"true", "1", "yes", "on"}

cfg = {
    "defaultCurrency": text(item.get("cfg_default_currency") or "USD").upper(),
    "defaultTaxRate": num(item.get("cfg_default_tax_rate")) if item.get("cfg_default_tax_rate") is not None else 0,
    "taxTolerance": num(item.get("cfg_tax_tolerance")) if item.get("cfg_tax_tolerance") is not None else 0.01,
    "subtotalTolerance": num(item.get("cfg_subtotal_tolerance")) if item.get("cfg_subtotal_tolerance") is not None else 0.01,
    "patternConfidenceThreshold": num(item.get("cfg_pattern_confidence_threshold")) if item.get("cfg_pattern_confidence_threshold") is not None else 0.9,
    "recurringErrorThreshold": num(item.get("cfg_recurring_error_threshold")) if item.get("cfg_recurring_error_threshold") is not None else 3,
    "aiConfidenceThreshold": num(item.get("cfg_ai_confidence_threshold")) if item.get("cfg_ai_confidence_threshold") is not None else 0.7,
    "enablePatternLearning": to_bool(item.get("cfg_enable_pattern_learning"), True),
    "requiredFields": [v.strip() for v in text(item.get("cfg_required_fields")).split(",") if v.strip()],
}

unit_aliases = {
    "EACH": "EA", "EACHES": "EA", "PIECE": "EA", "PIECES": "EA", "PCS": "EA", "PC": "EA",
    "KILOGRAM": "KG", "KILOGRAMS": "KG", "KGS": "KG",
    "GRAM": "G", "GRAMS": "G",
    "LITER": "L", "LITERS": "L", "LITRE": "L", "LITRES": "L",
    "MILLILITER": "ML", "MILLILITERS": "ML", "MILLILITRE": "ML", "MILLILITRES": "ML",
}

raw_unit = text(src.get("unit") or src.get("uom")).upper()

record = {
    "supplier": text(src.get("supplier")),
    "item_code": text(src.get("item_code") or src.get("itemCode")),
    "description": text(src.get("description")),
    "category": text(src.get("category")),
    "quantity": num(src.get("quantity")),
    "unit": unit_aliases.get(raw_unit, raw_unit),
    "unit_price": num(src.get("unit_price") if src.get("unit_price") is not None else src.get("unitPrice")),
    "subtotal": num(src.get("subtotal")),
    "tax_rate": num(src.get("tax_rate") if src.get("tax_rate") is not None else src.get("taxRate")),
    "tax_amount": num(src.get("tax_amount") if src.get("tax_amount") is not None else src.get("taxAmount")),
    "currency": text(src.get("currency") or cfg["defaultCurrency"]).upper(),
    "document_id": text(src.get("document_id") or src.get("po_number") or src.get("invoice_number") or src.get("reference")),
}

errors = []
for field in cfg["requiredFields"]:
    value = record.get(field)
    if value in ("", None):
        errors.append({
            "field": field,
            "type": "MISSING_REQUIRED_FIELD",
            "actual": value,
            "expected": "non-empty value",
            "severity": "high",
            "reason": f"{field} is required.",
        })

if record["quantity"] is not None and record["quantity"] <= 0:
    errors.append({"field": "quantity", "type": "INVALID_QUANTITY", "actual": record["quantity"], "expected": "greater than 0", "severity": "high", "reason": "Quantity must be greater than zero."})

if record["unit_price"] is not None and record["unit_price"] < 0:
    errors.append({"field": "unit_price", "type": "INVALID_UNIT_PRICE", "actual": record["unit_price"], "expected": "0 or greater", "severity": "high", "reason": "Unit price cannot be negative."})

if record["tax_rate"] is not None and (record["tax_rate"] < 0 or record["tax_rate"] > 100):
    errors.append({"field": "tax_rate", "type": "INVALID_TAX_RATE", "actual": record["tax_rate"], "expected": "0 to 100", "severity": "high", "reason": "Tax rate must be between 0 and 100."})

expected_subtotal = None
if record["quantity"] is not None and record["unit_price"] is not None:
    expected_subtotal = round2(record["quantity"] * record["unit_price"])

if record["subtotal"] is not None and expected_subtotal is not None and abs(record["subtotal"] - expected_subtotal) > cfg["subtotalTolerance"]:
    errors.append({"field": "subtotal", "type": "SUBTOTAL_MISMATCH", "actual": record["subtotal"], "expected": expected_subtotal, "severity": "high", "reason": "Subtotal does not match quantity multiplied by unit price."})

effective_subtotal = record["subtotal"] if record["subtotal"] is not None else expected_subtotal
effective_tax_rate = record["tax_rate"] if record["tax_rate"] is not None else cfg["defaultTaxRate"]
expected_tax = round2(effective_subtotal * effective_tax_rate / 100) if effective_subtotal is not None else None

if record["tax_amount"] is not None and expected_tax is not None and abs(record["tax_amount"] - expected_tax) > cfg["taxTolerance"]:
    errors.append({"field": "tax_amount", "type": "TAX_MISMATCH", "actual": record["tax_amount"], "expected": expected_tax, "severity": "high", "reason": "Tax amount does not match subtotal and tax rate."})

signature_parts = [
    record["supplier"].upper(),
    record["item_code"].upper(),
    record["category"].upper(),
    record["unit"].upper(),
    str(effective_tax_rate if effective_tax_rate is not None else ""),
]
pattern_key = "|".join(signature_parts)

return [{
    "json": {
        "record": record,
        "config": cfg,
        "validation": {
            "has_errors": len(errors) > 0,
            "error_count": len(errors),
            "errors": errors,
            "expected_subtotal": expected_subtotal,
            "expected_tax": expected_tax,
        },
        "pattern_key": pattern_key,
    }
}]

