={{ (() => {
  if (!$json.text) return false;

  const parsed = JSON.parse(
    $json.text.replace(/```json|```/g, '').trim()
  );

  return Boolean(parsed.anomaly_detected);
})() }}

={{ (() => {
  const deterministic = Boolean($json.validation?.has_errors);
  const historical = Boolean($json.known_pattern_matched);

  let aiDetected = false;
  let aiConfidence = 0;

  if ($json.text) {
    const parsed = JSON.parse(
      $json.text.replace(/```json|```/g, '').trim()
    );

    aiDetected = Boolean(parsed.anomaly_detected);
    aiConfidence = Number(parsed.confidence || 0);
  }

  return deterministic
    || historical
    || (
      aiDetected
      && aiConfidence >= Number($vars.cfg_ai_confidence_threshold || 0.7)
    );
})() }}

={{ (() => {
  if ($json.known_pattern_matched) {
    return 'historical_pattern';
  }

  if ($json.text) {
    const parsed = JSON.parse(
      $json.text.replace(/```json|```/g, '').trim()
    );

    if (parsed.anomaly_detected) {
      return 'gemini';
    }
  }

  if ($json.validation?.has_errors) {
    return 'deterministic_rule';
  }

  return 'none';
})() }}

={{ (() => {
  if ($json.known_pattern_matched) {
    return Number($json.confidence || 0);
  }

  if ($json.text) {
    const parsed = JSON.parse(
      $json.text.replace(/```json|```/g, '').trim()
    );

    if (parsed.anomaly_detected) {
      return Number(parsed.confidence || 0);
    }
  }

  if ($json.validation?.has_errors) {
    return 1;
  }

  return 0;
})() }}

={{ [
  ...($json.validation?.errors || []),

  ...(
    $json.known_pattern_matched && $json.historical_issue
      ? [$json.historical_issue]
      : []
  ),

  ...(
    $json.text
      ? (() => {
          const parsed = JSON.parse(
            $json.text.replace(/```json|```/g, '').trim()
          );

          const corrections = parsed.suggested_corrections || {};

          const out = (parsed.anomalies || []).map(anomaly => ({
            field: anomaly.field || '',
            type: 'AI_ANOMALY',
            actual: $json.record?.[anomaly.field] ?? '',
            suggested_value: corrections[anomaly.field] ?? '',
            reason: anomaly.issue || '',
            confidence: Number(parsed.confidence || 0),
            source: 'gemini'
          }));

          return out;
        })()
      : []
  )
] }}
